// Raw commands are decoded; results/kernel/financial state are observations
// regenerated by actual source execution, never live-state imports.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NativeStepCheckpointPinV1 {
    pub head: NativeStepHeadV1,
    pub foundation: NativeMainArchivePin,
    pub current: NativePhysicalBinding,
    pub archive_sha256: [u8; 32],
}
pub enum NativeStepReexecutionOwnerV1 {
    Origin(Box<SourceCompactIndex>),
    Atomic(Box<SourceMainNativeSessionV13>),
    AtomicFailure(Box<RejectedNativeMainReexecution>),
    Steps(Box<SourceMainNativeStepSessionV1>),
}
pub struct RejectedNativeStepReexecutionV1 {
    pub error: NativeStepSessionError,
    pub owner: NativeStepReexecutionOwnerV1,
}
impl core::fmt::Debug for RejectedNativeStepReexecutionV1 {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_struct("RejectedNativeStepReexecutionV1")
            .field("error", &self.error)
            .finish_non_exhaustive()
    }
}
fn native_step_blob(out: &mut Vec<u8>, bytes: &[u8]) -> Result<(), NativeStepSessionError> {
    if bytes.len() > 256 * 1024 * 1024
        || out.len().saturating_add(bytes.len()).saturating_add(4) > 64 * 1024 * 1024
    {
        return Err(NativeStepSessionError::Capacity);
    }
    out.extend_from_slice(&(bytes.len() as u32).to_be_bytes());
    out.extend_from_slice(bytes);
    Ok(())
}
fn native_step_read_blob<'a>(
    cursor: &mut crate::codec::Cursor<'a>,
) -> Result<&'a [u8], NativeStepSessionError> {
    let n = cursor.u32().map_err(|_| native_step_invalid())? as usize;
    if n > 256 * 1024 * 1024 {
        return Err(NativeStepSessionError::Capacity);
    }
    cursor.take(n).map_err(|_| native_step_invalid())
}
fn native_step_pin_value(pin: &NativeMainArchivePin) -> V {
    obj(&[
        ("headCount", s(&pin.head.commands.to_string())),
        ("head", s(&hex(&pin.head.commitment))),
        ("foundationCount", s(&pin.foundation.commands.to_string())),
        ("foundationHead", s(&hex(&pin.foundation.commitment))),
        ("origin", physical_value(&pin.origin)),
        ("current", physical_value(&pin.current)),
        ("archive", s(&hex(&pin.archive_sha256))),
    ])
}
struct NativeRecordedStepV1 {
    command: MainStepCommandV1,
    result: Vec<u8>,
    kernel: Vec<u8>,
    native: Vec<u8>,
    financial: [u8; 32],
    head: [u8; 32],
}
struct NativeStepArchiveInputV1 {
    profile: NativeStepProfileV1,
    foundation: Vec<u8>,
    generation: u64,
    records: Vec<NativeRecordedStepV1>,
}
fn native_step_inspect_archive(
    bytes: &[u8],
    expected: &NativeStepCheckpointPinV1,
    selected_profile: NativeStepProfileV1,
) -> Result<NativeStepArchiveInputV1, NativeStepSessionError> {
    if bytes.len() > 64 * 1024 * 1024 {
        return Err(NativeStepSessionError::Capacity);
    }
    if sha256(bytes) != expected.archive_sha256 {
        return Err(NativeStepSessionError::WrongHead);
    }
    let payload = crate::codec::verify_crc(bytes).map_err(|_| native_step_invalid())?;
    let mut cursor = crate::codec::Cursor::new(payload);
    if cursor.take(5).map_err(|_| native_step_invalid())? != b"TLCR\x0d" {
        return Err(native_step_invalid());
    }
    let profile = match read_value(&mut cursor).map_err(|_| native_step_invalid())? {
        V::String(value) if value == NATIVE_STEP_PROFILE => NativeStepProfileV1::Immediate,
        V::String(value) if value == NATIVE_FILE_STEP_PROFILE => NativeStepProfileV1::FileRetries,
        _ => return Err(native_step_invalid()),
    };
    if profile != selected_profile {
        return Err(native_step_invalid());
    }
    let foundation = native_step_read_blob(&mut cursor)?.to_vec();
    if read_value(&mut cursor).map_err(|_| native_step_invalid())?
        != native_step_pin_value(&expected.foundation)
    {
        return Err(NativeStepSessionError::WrongPhysicalBinding);
    }
    let generation = cursor.u64().map_err(|_| native_step_invalid())?;
    let count = cursor.u32().map_err(|_| native_step_invalid())? as usize;
    if count > MAX_STEP_RECORDS + 1 || count as u64 != expected.head.commands {
        return Err(NativeStepSessionError::WrongHead);
    }
    let mut records = Vec::with_capacity(count);
    let mut last_physical = physical_value(&expected.foundation.current);
    for _ in 0..count {
        let command = native_step_decode_command(native_step_read_blob(&mut cursor)?)?;
        let result = native_step_read_blob(&mut cursor)?.to_vec();
        native_step_parse_fields(&result, "Native13/StepResult/v1")?;
        let kernel = native_step_read_blob(&mut cursor)?.to_vec();
        native_step_parse_fields(&kernel, "Native13/StepKernel/v1")?;
        let native = native_step_read_blob(&mut cursor)?.to_vec();
        native_step_parse_fields(&native, "Native13/StepNative/v1")?;
        let financial = cursor.fixed::<32>().map_err(|_| native_step_invalid())?;
        let head = cursor.fixed::<32>().map_err(|_| native_step_invalid())?;
        if read_value(&mut cursor).map_err(|_| native_step_invalid())? != last_physical {
            return Err(NativeStepSessionError::WrongPhysicalBinding);
        }
        last_physical = read_value(&mut cursor).map_err(|_| native_step_invalid())?;
        if !matches!(last_physical, V::Object(_)) {
            return Err(NativeStepSessionError::RecoveryRequired);
        }
        records.push(NativeRecordedStepV1 {
            command,
            result,
            kernel,
            native,
            financial,
            head,
        });
    }
    if cursor.fixed::<32>().map_err(|_| native_step_invalid())? != expected.head.commitment {
        return Err(NativeStepSessionError::WrongHead);
    }
    if read_value(&mut cursor).map_err(|_| native_step_invalid())?
        != physical_value(&expected.current)
        || last_physical != physical_value(&expected.current)
    {
        return Err(NativeStepSessionError::WrongPhysicalBinding);
    }
    cursor.end().map_err(|_| native_step_invalid())?;
    Ok(NativeStepArchiveInputV1 {
        profile,
        foundation,
        generation,
        records,
    })
}
impl SourceMainNativeStepSessionV1 {
    pub fn checkpoint(
        &self,
    ) -> Result<(Vec<u8>, NativeStepCheckpointPinV1), NativeStepSessionError> {
        let head = self.head()?;
        if self.receipts().count() as u64 != head.commands {
            return Err(NativeStepSessionError::PublicationBlocked(
                "complete prior history is in published segments".into(),
            ));
        }
        if self.requires_recovery() {
            return Err(NativeStepSessionError::RecoveryRequired);
        }
        let current = physical(self.index())
            .map_err(|error| NativeStepSessionError::Backend(format!("{error:?}")))?;
        let native_error =
            |error: NativeMainSessionError| NativeStepSessionError::Backend(format!("{error:?}"));
        let mut bytes = b"TLCR\x0d".to_vec();
        frame(&mut bytes, &s(self.profile().identifier())).map_err(native_error)?;
        native_step_blob(&mut bytes, self.foundation_checkpoint())?;
        frame(&mut bytes, &native_step_pin_value(self.foundation_pin())).map_err(native_error)?;
        bytes.extend_from_slice(&self.initial_generation().to_be_bytes());
        bytes.extend_from_slice(&(self.receipts().count() as u32).to_be_bytes());
        for receipt in self.receipts() {
            native_step_blob(
                &mut bytes,
                self.command_field_frames(receipt.sequence as usize)
                    .ok_or_else(native_step_invalid)?,
            )?;
            native_step_blob(&mut bytes, &receipt.result_frames)?;
            native_step_blob(&mut bytes, &receipt.kernel_frames)?;
            native_step_blob(&mut bytes, &receipt.native_frames)?;
            bytes.extend_from_slice(&receipt.financial_commitment);
            bytes.extend_from_slice(&receipt.head);
            frame(&mut bytes, &physical_value(&receipt.before)).map_err(native_error)?;
            frame(
                &mut bytes,
                &receipt.after.as_ref().map_or(V::Null, physical_value),
            )
            .map_err(native_error)?;
        }
        bytes.extend_from_slice(&head.commitment);
        frame(&mut bytes, &physical_value(&current)).map_err(native_error)?;
        let bytes = crate::codec::with_crc(bytes).map_err(|_| NativeStepSessionError::Capacity)?;
        let pin = NativeStepCheckpointPinV1 {
            head,
            foundation: self.foundation_pin().clone(),
            current,
            archive_sha256: sha256(&bytes),
        };
        Ok((bytes, pin))
    }
    pub fn reexecute(
        bytes: &[u8],
        expected: &NativeStepCheckpointPinV1,
        index: SourceCompactIndex,
        expected_raw_origin: &NativePhysicalBinding,
    ) -> Result<Self, Box<RejectedNativeStepReexecutionV1>> {
        Self::reexecute_profile(
            bytes,
            expected,
            index,
            expected_raw_origin,
            NativeStepProfileV1::Immediate,
        )
    }
    pub fn reexecute_with_file_retries(
        bytes: &[u8],
        expected: &NativeStepCheckpointPinV1,
        index: SourceCompactIndex,
        expected_raw_origin: &NativePhysicalBinding,
    ) -> Result<Self, Box<RejectedNativeStepReexecutionV1>> {
        Self::reexecute_profile(
            bytes,
            expected,
            index,
            expected_raw_origin,
            NativeStepProfileV1::FileRetries,
        )
    }
    fn reexecute_profile(
        bytes: &[u8],
        expected: &NativeStepCheckpointPinV1,
        index: SourceCompactIndex,
        expected_raw_origin: &NativePhysicalBinding,
        selected_profile: NativeStepProfileV1,
    ) -> Result<Self, Box<RejectedNativeStepReexecutionV1>> {
        let archive = match native_step_inspect_archive(bytes, expected, selected_profile) {
            Ok(input) => input,
            Err(error) => {
                return Err(Box::new(RejectedNativeStepReexecutionV1 {
                    error,
                    owner: NativeStepReexecutionOwnerV1::Origin(Box::new(index)),
                }))
            }
        };
        let owner = match SourceMainNativeSessionV13::reexecute(
            &archive.foundation,
            &expected.foundation,
            index,
            expected_raw_origin,
        ) {
            Ok(owner) => owner,
            Err(rejected) => {
                return Err(Box::new(RejectedNativeStepReexecutionV1 {
                    error: NativeStepSessionError::Backend(format!("{:?}", rejected.error)),
                    owner: NativeStepReexecutionOwnerV1::AtomicFailure(rejected),
                }))
            }
        };
        let actual_pin = match owner.expectation() {
            Ok(pin) => pin,
            Err(error) => {
                return Err(Box::new(RejectedNativeStepReexecutionV1 {
                    error: NativeStepSessionError::Backend(format!("{error:?}")),
                    owner: NativeStepReexecutionOwnerV1::Atomic(Box::new(owner)),
                }))
            }
        };
        let mut session =
            match Self::adopt_profile(owner, &actual_pin, archive.generation, archive.profile) {
                Ok(session) => session,
                Err(rejected) => {
                    return Err(Box::new(RejectedNativeStepReexecutionV1 {
                        error: rejected.error.clone(),
                        owner: NativeStepReexecutionOwnerV1::Atomic(Box::new(
                            rejected.into_owner(),
                        )),
                    }))
                }
            };
        let checked = (|| {
            for expected_record in archive.records {
                let next = session.expectation()?;
                let actual = session.apply_step(&next, expected_record.command)?;
                if actual.result_frames != expected_record.result
                    || actual.kernel_frames != expected_record.kernel
                    || actual.native_frames != expected_record.native
                    || actual.financial_commitment != expected_record.financial
                    || actual.head != expected_record.head
                {
                    return Err(NativeStepSessionError::Backend(
                        "actual step reexecution mismatch".into(),
                    ));
                }
            }
            if session.head()? != expected.head {
                return Err(NativeStepSessionError::WrongHead);
            }
            Ok(())
        })();
        match checked {
            Ok(()) => Ok(session),
            Err(error) => Err(Box::new(RejectedNativeStepReexecutionV1 {
                error,
                owner: NativeStepReexecutionOwnerV1::Steps(Box::new(session)),
            })),
        }
    }
}
